import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.mrTIYZc5.js";const g=JSON.parse('{"title":"Production Readiness","description":"","frontmatter":{},"headers":[],"relativePath":"guide/production-readiness.md","filePath":"guide/production-readiness.md"}'),r={name:"guide/production-readiness.md"};function a(s,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="production-readiness" tabindex="-1">Production Readiness <a class="header-anchor" href="#production-readiness" aria-label="Permalink to &quot;Production Readiness&quot;">​</a></h1><p>This checklist provides the critical configuration steps and architectural requirements for deploying DSO in high-security production environments.</p><hr><h2 id="_1-authentication-identity-checklist" tabindex="-1">1. Authentication &amp; Identity Checklist <a class="header-anchor" href="#_1-authentication-identity-checklist" aria-label="Permalink to &quot;1. Authentication &amp; Identity Checklist&quot;">​</a></h2><ul><li>[ ] <strong>Use Machine Identity</strong>: Never use static AWS Access Keys, Azure Client Secrets, or Vault Tokens on the host. <ul><li><strong>AWS</strong>: Configure the host with an IAM Instance Profile.</li><li><strong>Azure</strong>: Enable Managed Identity on the virtual machine.</li><li><strong>HashiCorp Vault</strong>: Use AppRole with response wrapping.</li></ul></li><li>[ ] <strong>Least Privilege Policy</strong>: Ensure the host&#39;s identity only has <code>GetSecretValue</code> permissions for the specific secrets DSO is managing. Avoid <code>secretsmanager:*</code> or equivalent broad permissions.</li></ul><h2 id="_2-infrastructure-hardening" tabindex="-1">2. Infrastructure Hardening <a class="header-anchor" href="#_2-infrastructure-hardening" aria-label="Permalink to &quot;2. Infrastructure Hardening&quot;">​</a></h2><ul><li>[ ] <strong>Restricted Unix Socket</strong>: Ensure the DSO socket (<code>/run/docker/plugins/dso.sock</code>) is only accessible by the <code>root</code> user and the <code>docker</code> group.</li><li>[ ] <strong>Dedicated Service User</strong>: Run the <code>dso-agent</code> as a dedicated non-root user if your environment supports this (requires specific Docker socket permissions).</li><li>[ ] <strong>No Host-Path Mounts</strong>: Audit your <code>docker-compose.yaml</code> and ensure no plaintext secrets are being mounted from the host filesystem. Use DSO&#39;s <code>RAMfs</code> injection instead.</li></ul><h2 id="_3-operational-configuration" tabindex="-1">3. Operational Configuration <a class="header-anchor" href="#_3-operational-configuration" aria-label="Permalink to &quot;3. Operational Configuration&quot;">​</a></h2><ul><li>[ ] <strong>Rotation Strategies</strong>: Define explicit rotation strategies (<code>sighup</code>, <code>rolling</code>, or <code>restart</code>) in your container labels (<code>dso.strategy</code>).</li><li>[ ] <strong>Healthchecks</strong>: Always define a <code>healthcheck</code> in your Docker Compose service. DSO uses this to verify a successful rotation before deactivating the older secret version.</li><li>[ ] <strong>Polling Interval</strong>: Adjust <code>agent.watch.polling_interval</code> based on your compliance needs. Standard is 2 minutes; high-security environments may require 30 seconds.</li></ul><h2 id="_4-observability-auditing" tabindex="-1">4. Observability &amp; Auditing <a class="header-anchor" href="#_4-observability-auditing" aria-label="Permalink to &quot;4. Observability &amp; Auditing&quot;">​</a></h2><ul><li>[ ] <strong>Structured Logging</strong>: Enable JSON logging in the DSO agent.</li><li>[ ] <strong>Log Export</strong>: Stream DSO&#39;s log output to a centralized SIEM (Splunk, Datadog, ELK) for real-time monitoring of secret access events.</li><li>[ ] <strong>Alerting</strong>: Set alerts for <code>level=ERROR</code> in the DSO logs, which typically indicate vault authentication failures or failed secret injections.</li></ul><hr><h2 id="deployment-architectures" tabindex="-1">Deployment Architectures <a class="header-anchor" href="#deployment-architectures" aria-label="Permalink to &quot;Deployment Architectures&quot;">​</a></h2><h3 id="edge-single-node-deployment" tabindex="-1">Edge / Single-Node Deployment <a class="header-anchor" href="#edge-single-node-deployment" aria-label="Permalink to &quot;Edge / Single-Node Deployment&quot;">​</a></h3><p>For edge devices running on-premise, ensure that the DSO binary is protected by OS-level file integrity monitoring (FIM) and that the edge host has limited network access to only the required Vault endpoints.</p><h3 id="cloud-virtual-machines-ec2-azure-vm" tabindex="-1">Cloud Virtual Machines (EC2/Azure VM) <a class="header-anchor" href="#cloud-virtual-machines-ec2-azure-vm" aria-label="Permalink to &quot;Cloud Virtual Machines (EC2/Azure VM)&quot;">​</a></h3><p>In cloud environments, leverage the cloud&#39;s native IAM system. Use VPC Endpoints (AWS) or Private Links (Azure) to communicate with the Vault over private network paths, avoiding any traversal of the public internet.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/design-principles.html">Design Principles</a></strong>: The core pillars of the project.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Detailed threat mitigations.</li><li><strong><a href="/docs/guide/troubleshooting.html">Troubleshooting</a></strong>: Diagnosing common production issues.</li></ul>',19)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
